<template><div class="flex gap-2 justify-center"><button v-for="l in langs" :key="l.code" @click="$emit('change', l.code)" class="px-3 py-1 rounded-md text-sm font-medium transition border" :class="active===l.code ? 'bg-teal-500 text-black border-teal-400 shadow' : 'bg-neutral-800 text-neutral-200 hover:bg-neutral-700 border-neutral-700'">{{ l.flag }} {{ l.label }}</button></div></template><script setup>defineProps({ active:String });const langs=[{code:'creole',label:'Kreyòl',flag:'🇬🇵'},{code:'fr',label:'Français',flag:'🇫🇷'},{code:'es',label:'Español',flag:'🇪🇸'}];</script>